-- GENERADO POR scripts/build-seed.mjs — no editar a mano.
-- Editar supabase/seed/catalog.mjs y ejecutar `npm run seed:build`.

begin;

-- Juegos ------------------------------------------------------------------
on conflict (slug) do update
  set name = excluded.name, release_year = excluded.release_year;

-- Sliders -----------------------------------------------------------------
on conflict (game_id, slug, applies_to) do update
  set category      = excluded.category,
      name          = excluded.name,
      min_value     = excluded.min_value,
      max_value     = excluded.max_value,
      default_value = excluded.default_value,
      sort_order    = excluded.sort_order;

-- Limpieza: lo que ya no está en el catálogo -------------------------------
delete from public.slider_definitions
where game_id = (select id from public.games where slug = 'fc27')
  and slug not in ('sprint_speed', 'acceleration', 'shot_error', 'shot_speed', 'finesse_shot_error', 'finesse_shot_speed', 'chip_shot_error', 'chip_shot_speed', 'low_driven_shot_error', 'low_driven_shot_speed', 'power_shot_error', 'power_shot_speed', 'header_shot_error', 'pass_error', 'pass_speed', 'header_pass_error', 'through_pass_error', 'through_pass_speed', 'lobbed_through_pass_error', 'lobbed_through_pass_speed', 'lob_pass_error', 'lob_pass_speed', 'cross_error', 'cross_height', 'power_bar', 'first_touch_error', 'interception_error', 'deflection_error', 'jog_dribbling_error', 'sprint_dribbling_error', 'controlled_sprint_dribbling_error', 'tackle_assistance', 'physicality_impact', 'jockey_speed', 'sprint_jockey_speed', 'goalkeeper_ability', 'gk_deflection_error', 'marking', 'run_frequency', 'line_height', 'line_length', 'line_width', 'defensive_positioning', 'injury_frequency', 'injury_severity', 'cpu_defending_aggression', 'cpu_stand_tackle_aggression', 'cpu_slide_tackle_aggression', 'cpu_professional_frequency', 'cpu_buildup_speed', 'cpu_shot_frequency', 'cpu_chip_shot_frequency', 'cpu_low_driven_shot_frequency', 'cpu_finesse_shot_frequency', 'cpu_long_shot_frequency', 'cpu_power_shot_frequency', 'cpu_first_touch_pass_frequency', 'cpu_cross_frequency', 'cpu_early_cross_frequency', 'cpu_dribble_frequency', 'cpu_skill_move_frequency');

delete from public.slider_definitions
where game_id = (select id from public.games where slug = 'fc26')
  and slug not in ('sprint_speed', 'acceleration', 'shot_error', 'shot_speed', 'header_shot_error', 'pass_error', 'pass_speed', 'header_pass_error', 'power_bar', 'first_touch_error', 'interception_error', 'deflection_error', 'tackle_assistance', 'goalkeeper_ability', 'marking', 'run_frequency', 'line_height', 'line_length', 'line_width', 'defensive_positioning', 'injury_frequency', 'injury_severity', 'cpu_tackle_aggression', 'cpu_buildup_speed', 'cpu_shot_frequency', 'cpu_first_touch_pass_frequency', 'cpu_cross_frequency', 'cpu_dribble_frequency', 'cpu_flair_frequency');

commit;
